// Cryptographically random credentials and pairing codes, generated by swift-crypto.

import Crypto
import Foundation

/// Random secret material.
public enum RandomTokens {
    /// `byteCount` random bytes from the platform CSPRNG (via swift-crypto).
    public static func bytes(_ byteCount: Int) -> Data {
        let key = SymmetricKey(size: SymmetricKeySize(bitCount: max(8, byteCount) * 8))
        return key.withUnsafeBytes { Data($0) }
    }

    /// A URL-safe credential with 256 bits of entropy.
    public static func credential() -> String {
        Base64URL.encode(bytes(32))
    }

    /// A short human-enterable code from an unambiguous alphabet (Crockford base 32).
    public static func code(length: Int) -> String {
        let alphabet = Array("0123456789ABCDEFGHJKMNPQRSTVWXYZ")
        var result = ""
        var pool = [UInt8](bytes(length * 2))
        while result.count < length {
            if pool.isEmpty { pool = [UInt8](bytes(length * 2)) }
            let byte = pool.removeLast()
            // Rejection sampling keeps the distribution uniform over the 32 symbols.
            if byte < 224 { result.append(alphabet[Int(byte) % 32]) }
        }
        return result
    }
}

/// Base64url without padding (RFC 4648 §5), as used by JWS and credentials.
public enum Base64URL {
    public static func encode(_ data: Data) -> String {
        data.base64EncodedString().replacingOccurrences(of: "+", with: "-").replacingOccurrences(of: "/", with: "_")
            .replacingOccurrences(of: "=", with: "")
    }

    public static func decode(_ text: String) -> Data? {
        var value = text.replacingOccurrences(of: "-", with: "+").replacingOccurrences(of: "_", with: "/")
        while value.count % 4 != 0 { value += "=" }
        return Data(base64Encoded: value)
    }
}
